// PASO 1: Mostrar proyectos según la categoría seleccionada.
document.querySelector('#filters').onclick = e => {
  const b = e.target.closest('[data-filter]');
  if (!b) return;
  document.querySelectorAll('[data-filter]').forEach(x => x.setAttribute('aria-pressed', x === b));
  document.querySelectorAll('[data-kind]').forEach(x => x.hidden = b.dataset.filter !== 'Todos' && x.dataset.kind !== b.dataset.filter);
}; // PASO 2: Definir 25 minutos y las referencias a los controles.
let remaining = 1500,
  deadline = 0,
  interval = null;
const timer = document.querySelector('#timer'),
  start = document.querySelector('#start'); // PASO 3: Convertir los segundos al formato minutos:segundos.
function render() {
  timer.textContent = Math.floor(remaining / 60).toString().padStart(2, '0') + ':' + (remaining % 60).toString().padStart(2, '0');
} // PASO 4: Detener las actualizaciones sin perder el tiempo restante.
function pause() {
  clearInterval(interval);
  interval = null;
  start.textContent = 'Continuar';
} // PASO 5: Calcular el tiempo restante con la hora real.
function tick() {
  remaining = Math.max(0, Math.ceil((deadline - Date.now()) / 1000));
  render();
  if (!remaining) {
    pause();
    start.textContent = 'Volver a iniciar';
  }
} // PASO 6: Iniciar, pausar o continuar el temporizador.
start.onclick = () => {
  if (interval) {
    tick();
    pause();
    return;
  }
  if (!remaining) remaining = 1500;
  deadline = Date.now() + remaining * 1000;
  start.textContent = 'Pausar';
  interval = setInterval(tick, 250);
}; // PASO 7: Restaurar los 25 minutos.
document.querySelector('#reset').onclick = () => {
  pause();
  remaining = 1500;
  start.textContent = 'Iniciar';
  render();
};
